// Works for both Chat app types: "Workspace add-on" events (body.chat) and classic Chat API events (body.type).
const body = $json.body || {};
const allowed = String($json.allowed_chat_users || '').toLowerCase().split(',').map((s) => s.trim()).filter(Boolean);
const addon = !!body.chat;
let kind, text, email;
if (addon) {
  const p = body.chat.messagePayload;
  kind = p ? 'message' : 'other';
  text = p ? (p.message.argumentText || p.message.text || '') : '';
  email = (body.chat.user && body.chat.user.email) || (p && p.message.sender && p.message.sender.email) || '';
} else {
  kind = body.type === 'MESSAGE' ? 'message' : 'other';
  text = (body.message && (body.message.argumentText || body.message.text)) || '';
  email = (body.user && body.user.email) || '';
}
const wrap = (t) => (addon ? { hostAppDataAction: { chatDataAction: { createMessageAction: { message: { text: t } } } } } : { text: t });
const help = 'Write which month you want, for example "September sales report" or "先月の売上報告". I make the slides and send you the link.';
let reply = null;
if (kind !== 'message') reply = wrap(help);
else if (!allowed.includes(String(email).toLowerCase())) reply = wrap('Sorry, ' + (email || 'this account') + ' is not on the list of people who can make reports.');
else if (!text.trim()) reply = wrap(help);
return [{ json: { ok: !reply, reply, Request: text.trim(), source: 'chat', addon, sender: email } }];

// Data tab -> records with a date, a group, a value (1 per row when value_column is empty) and an optional distinct key.
const cfg = $('Config').first().json;
const rows = $json.values || [];
const head = (rows[0] || []).map((h) => String(h).trim());
const need = [cfg.date_column, cfg.group_column, cfg.value_column, cfg.distinct_column].filter(Boolean);
const missing = need.filter((h) => !head.includes(h));
if (missing.length) throw new Error('The ' + cfg.data_tab + ' tab needs the columns ' + need.join(', ') + ' (set in Config). Missing: ' + missing.join(', ') + '. Found: ' + head.join(', '));
const toDate = (v) => (typeof v === 'number' ? new Date(Date.UTC(1899, 11, 30) + v * 86400000).toISOString().slice(0, 10) : String(v).trim().slice(0, 10).replace(/\//g, '-'));
const records = rows.slice(1).filter((r) => r.some((c) => String(c).trim() !== '')).map((r) => {
  const o = Object.fromEntries(head.map((h, i) => [h, r[i] ?? '']));
  return {
    date: toDate(o[cfg.date_column]),
    group: String(o[cfg.group_column]).trim() || '(blank)',
    value: cfg.value_column ? Number(String(o[cfg.value_column]).replace(/[,\s¥$€£]/g, '')) : 1,
    key: cfg.distinct_column ? String(o[cfg.distinct_column]).trim() : '',
  };
});
const bad = records.filter((s) => !/^\d{4}-\d{2}-\d{2}$/.test(s.date) || !Number.isFinite(s.value));
if (bad.length) throw new Error(bad.length + ' rows in ' + cfg.data_tab + ' have a date or value that cannot be read, e.g. ' + JSON.stringify(bad[0]));
return [{ json: { records } }];

// Code computes the month from the words and compares it with what Claude read.
const cfg = $('Config').first().json;
const request = String(cfg.request || '').trim();
const { records } = $('Parse the data').first().json;
let r;
try { r = JSON.parse(String($json.text ?? '').match(/\{[\s\S]*\}/)[0]); }
catch (e) { return [{ json: { ok: false, problem: 'Could not read the AI answer as JSON. Try again or write the month more simply.' } }]; }
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFKC').replace(/\s+/g, ' ').trim();
const req = norm(request);
const today = DateTime.now().setZone(cfg.timezone);
const monthNames = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const pick = (mm) => { let y = today.year; if (mm > today.month) y -= 1; return y + '-' + String(mm).padStart(2, '0'); };
function monthFromWords(w) {
  const s = norm(w);
  let m;
  if ((m = s.match(/(\d{4})\s*[-\/年.]\s*(\d{1,2})/))) return m[1] + '-' + m[2].padStart(2, '0');
  if ((m = s.match(/(\d{1,2})\s*月/))) return pick(Number(m[1]));
  for (let i = 0; i < 12; i++) if (s.includes(monthNames[i]) || new RegExp('\\b' + monthNames[i].slice(0, 3) + '\\b').test(s)) return pick(i + 1);
  if (/先月|前月|last month/.test(s)) return today.minus({ months: 1 }).toFormat('yyyy-MM');
  if (/今月|this month/.test(s)) return today.toFormat('yyyy-MM');
  return null;
}
const problems = [];
let month = null;
if (!r.month_words) problems.push('The request does not say which month. Write it, for example "September", "9月" or "2026-09".');
else if (!req.includes(norm(r.month_words))) problems.push('The month words "' + r.month_words + '" are not in the request.');
else {
  month = monthFromWords(r.month_words);
  if (!month) problems.push('Could not read a month from "' + r.month_words + '".');
  else if (month !== r.month) problems.push('The AI read the month as ' + r.month + ', but "' + r.month_words + '" means ' + month + '.');
  else if (month > today.toFormat('yyyy-MM')) problems.push(month + ' is in the future.');
  else if (!records.some((s) => s.date.startsWith(month))) problems.push('There is no data for ' + month + ' in the ' + cfg.data_tab + ' tab.');
}
return [{ json: { ok: problems.length === 0, problem: problems.join(' '), month, read: r } }];

// Every number on the slides comes from here. A month still in progress is compared with the same days of the month before.
const cfg = $('Config').first().json;
const { records } = $('Parse the data').first().json;
const { month } = $json;
const today = DateTime.now().setZone(cfg.timezone);
const start = DateTime.fromFormat(month, 'yyyy-MM', { zone: cfg.timezone });
const prevStart = start.minus({ months: 1 });
const prevMonth = prevStart.toFormat('yyyy-MM');
const inProgress = month === today.toFormat('yyyy-MM');
const lastDay = inProgress ? today.day : start.endOf('month').day;
const dayOf = (s) => Number(s.date.slice(8, 10));
const cur = records.filter((s) => s.date.startsWith(month) && dayOf(s) <= lastDay);
const prev = records.filter((s) => s.date.startsWith(prevMonth) && (!inProgress || dayOf(s) <= lastDay));
const dec = Number(cfg.decimals);
const fmt = (x) => {
  if (cfg.value_format === 'money') return new Intl.NumberFormat(cfg.number_locale, { style: 'currency', currency: cfg.currency, minimumFractionDigits: dec, maximumFractionDigits: dec }).format(x);
  const s = new Intl.NumberFormat(cfg.number_locale, { minimumFractionDigits: dec, maximumFractionDigits: dec }).format(x);
  return cfg.value_format === 'hours' ? s + ' h' : s;
};
const pct = (a, b) => (b ? (a / b - 1) * 100 : null);
const sign = (p) => (p === null ? 'n/a' : (p >= 0 ? '+' : '') + p.toFixed(1) + '%');
const sum = (arr) => arr.reduce((t, s) => t + s.value, 0);
const total = sum(cur), prevTotal = sum(prev);
const entries = cur.length;
const counting = !cfg.value_column; // one row = one record: total and entries are the same number
const distinct = cfg.distinct_column ? new Set(cur.map((s) => s.key).filter(Boolean)).size : null;
const average = entries && !counting ? total / entries : null;
const vs = pct(total, prevTotal);
const groups = [...new Set(records.map((s) => s.group))];
const byGroup = groups.map((g) => ({ group: g, cur: sum(cur.filter((s) => s.group === g)), prev: sum(prev.filter((s) => s.group === g)) }));
const top = [...byGroup].filter((x) => x.cur > 0).sort((a, b) => b.cur - a.cur).slice(0, Number(cfg.top_n));
const label = (d, last) => d.toFormat('LLL d') + '–' + d.set({ day: last }).toFormat('d') + ', ' + d.toFormat('yyyy');
const period = inProgress ? label(start, lastDay) + ' (month to date)' : start.toFormat('LLLL yyyy');
const prevPeriod = inProgress ? label(prevStart, lastDay) : prevStart.toFormat('LLLL yyyy');
const share = (x) => (total ? Math.round((x / total) * 100) : 0);
const topLines = top.map((x, i) => (i + 1) + '. ' + x.group + ': ' + fmt(x.cur) + ' (' + share(x.cur) + '% of the total, ' + sign(pct(x.cur, x.prev)) + ' vs ' + prevStart.toFormat('LLL') + ')');
const values = {
  report_title: cfg.report_title, period, prev_period: prevPeriod, prepared_on: today.toFormat('yyyy-MM-dd'),
  value_label: cfg.value_label, group_label: cfg.group_label, entry_label: cfg.entry_label, average_label: cfg.average_label, distinct_label: cfg.distinct_label,
  total: fmt(total), vs_last_month: sign(vs), entries: String(entries),
  average: average === null ? '-' : fmt(average), distinct: distinct === null ? '-' : String(distinct),
  top_groups: topLines.join('\n'),
};
// The facts the AI may use for its summary, written exactly as they appear on the slides.
const facts = [
  'Report: ' + cfg.report_title + '. Period: ' + period + '; compared with ' + prevPeriod,
  cfg.value_label + ': ' + fmt(total) + ' (' + prevPeriod + ': ' + fmt(prevTotal) + ', change ' + sign(vs) + ')',
  ...(counting ? [] : [cfg.entry_label + ': ' + entries + (average === null ? '' : '; ' + cfg.average_label + ': ' + fmt(average))]),
  ...(distinct === null ? [] : [cfg.distinct_label + ': ' + distinct]),
  ...topLines.map((l) => 'Top ' + cfg.group_label + ' ' + l),
];
// Every number string the summary is allowed to contain.
const allowed = new Set();
(facts.join('\n').match(/[+-]?[¥$€£]?\d+(?:,\d{3})*(?:\.\d+)?%?/g) || []).forEach((t) => allowed.add(t.replace(/^[+]/, '')));
const colName = (d) => d.toFormat('LLL yyyy') + (inProgress ? ' (to ' + lastDay + ')' : '');
const report = [[cfg.group_label, colName(start), colName(prevStart)], ...byGroup.map((x) => [x.group, x.cur, x.prev])];
// blank rows below clear what an earlier, longer report left behind
while (report.length < Math.max(30, groups.length + 1)) report.push(['', '', '']);
return [{ json: { month, values, facts, allowed: [...allowed], report, file_name: cfg.report_title + ' ' + month } }];

// Every number in the AI summary must be one of the computed numbers. If not, the summary is replaced by a plain one made by code.
const c = $('Compute the numbers').first().json;
const allowed = new Set(c.allowed);
let lines = [];
try { lines = JSON.parse(String($json.text ?? '').match(/\{[\s\S]*\}/)[0]).lines || []; } catch (e) { lines = []; }
lines = lines.map((l) => String(l).trim()).filter(Boolean).slice(0, 3);
const found = lines.flatMap((l) => (l.match(/[+-]?[¥$€£]?\d+(?:,\d{3})*(?:\.\d+)?%?/g) || []).map((t) => t.replace(/^[+]/, '')));
const unknown = found.filter((t) => !allowed.has(t));
const ok = lines.length > 0 && unknown.length === 0;
const plain = [
  c.values.value_label + ': ' + c.values.total + ' (' + c.values.vs_last_month + ' vs ' + c.values.prev_period + ').',
  c.values.entries !== c.values.total ? c.values.entry_label + ': ' + c.values.entries + '.' : '',
  c.values.top_groups ? 'Top ' + c.values.group_label + ': ' + c.values.top_groups.split('\n')[0].replace(/^1\. /, '') + '.' : '',
].filter(Boolean);
const summary = (ok ? lines : plain).map((l) => '• ' + l.replace(/^[•\-\*]\s*/, '')).join('\n');
const note = ok ? '' : (lines.length ? 'The AI summary used numbers that are not in the data (' + unknown.slice(0, 3).join(', ') + '), so a plain summary made by code was used.' : 'The AI summary could not be read, so a plain summary made by code was used.');
const values = { ...c.values, summary };
const requests = Object.entries(values).map(([k, v]) => ({ replaceAllText: { containsText: { text: '{{' + k + '}}', matchCase: true }, replaceText: String(v ?? '') } }));
return [{ json: { ok: true, values, requests, ai_summary_used: ok, summary_note: note, unknown, file_name: c.file_name } }];

// Put the chart where the template has a text box saying {{chart}}, as a plain image (not linked),
// so these slides do not change when the Report tab is rewritten for another month.
const cfg = $('Config').first().json;
const s = $('Check the summary').first().json;
const sheets = $('Find the chart').all(0)[0].json.sheets || [];
const tab = sheets.find((x) => x.properties && x.properties.title === cfg.report_tab);
const chartId = tab && tab.charts && tab.charts[0] ? tab.charts[0].chartId : null;
let box = null;
for (const slide of $json.slides || []) {
  for (const el of slide.pageElements || []) {
    const text = ((el.shape && el.shape.text && el.shape.text.textElements) || []).map((t) => (t.textRun ? t.textRun.content : '')).join('');
    if (text.includes('{{chart}}')) { box = { page: slide.objectId, el }; break; }
  }
  if (box) break;
}
const requests = [...s.requests];
let chart_note = '';
if (box && chartId !== null) {
  requests.push({ createSheetsChart: { spreadsheetId: cfg.spreadsheet_id, chartId, linkingMode: 'NOT_LINKED_IMAGE',
    elementProperties: { pageObjectId: box.page, size: box.el.size, transform: box.el.transform } } });
  requests.push({ deleteObject: { objectId: box.el.objectId } });
} else if (box) {
  requests.push({ replaceAllText: { containsText: { text: '{{chart}}', matchCase: true }, replaceText: '' } });
  chart_note = 'No chart was found on the ' + cfg.report_tab + ' tab, so the slides have no chart.';
} else if (chartId !== null) {
  chart_note = 'The template has no text box saying {{chart}}, so the chart was not added.';
}
return [{ json: { presentationId: $('Copy the template').all(0)[0].json.id, requests, chart_note } }];

// The error comes from the node that failed after its retries.
const labels = { 'Read the data': 'reading the data tab', 'Write the Report tab': 'writing the Report tab', 'Find the chart': 'looking for the chart', 'Copy the template': 'copying the Slides template', 'Read the copy': 'reading the copied slides', 'Fill in the slides': 'filling in the slides' };
const node = $prevNode.name;
const err = $json.error && ($json.error.message || $json.error);
return [{ json: { problem: 'Google returned an error while ' + (labels[node] || node) + (err ? ' (' + String(err).slice(0, 200) + ')' : '') + '.'
  + (['Read the copy', 'Fill in the slides'].includes(node) ? ' An unfinished copy of the template is left in Google Drive; delete it.' : '') } }];

// The link is a button: a URL in the text gets a preview made before the copy was filled in.
const addon = $('Config').first().json.addon;
let message;
if ($json.problem) message = { text: 'No slides were made. ' + $json.problem };
else {
  const s = $('Check the summary').all(0)[0].json;
  const chartNote = $('Plan the slide changes').all(0)[0].json.chart_note;
  const url = 'https://docs.google.com/presentation/d/' + $('Copy the template').all(0)[0].json.id + '/edit';
  message = {
    text: 'Report ready: ' + s.values.period + '\n' + s.values.value_label + ' ' + s.values.total + ' (' + s.values.vs_last_month + ' vs ' + s.values.prev_period + ').' + (s.summary_note ? '\nNote: ' + s.summary_note : '') + (chartNote ? '\nNote: ' + chartNote : ''),
    cardsV2: [{ cardId: 'report', card: { sections: [{ widgets: [{ buttonList: { buttons: [{ text: 'Open the slides', onClick: { openLink: { url } } }] } }] }] } }],
  };
}
const reply = addon ? { hostAppDataAction: { chatDataAction: { createMessageAction: { message } } } } : message;
return [{ json: { reply } }];
